        assertEquals("user42", got)

        // clear by id (no active session in this request) removes only that session
        client.get("/clear?id=$cookie").bodyAsText()
        val afterClear = client.get("/get") { header(HttpHeaders.Cookie, "sess=$cookie") }.bodyAsText()
        assertEquals("none", afterClear, "session should be gone after clear-by-id")
    }
}
